-- ====================================================================
-- CUSTOMER ANALYTICS & RFM SEGMENTATION
-- Business Questions:
-- 1. How many customers are new vs. returning (repeat purchase rate)?
-- 2. What are the RFM (Recency, Frequency, Monetary) scores for each customer?
-- 3. What percentage of revenue is generated by top-tier customer segments?
-- 4. What is the geographical distribution of high-value customers?
-- ====================================================================

-- 1. Repeat Customer Rate Analysis
WITH customer_order_counts AS (
    SELECT 
        c.customer_unique_id,
        COUNT(DISTINCT o.order_id) AS total_orders
    FROM customers c
    JOIN orders o ON c.customer_id = o.customer_id
    WHERE o.order_status = 'delivered'
    GROUP BY c.customer_unique_id
)
SELECT 
    COUNT(customer_unique_id) AS total_unique_customers,
    SUM(CASE WHEN total_orders = 1 THEN 1 ELSE 0 END) AS one_time_buyers,
    SUM(CASE WHEN total_orders > 1 THEN 1 ELSE 0 END) AS repeat_buyers,
    ROUND(
        SUM(CASE WHEN total_orders > 1 THEN 1.0 ELSE 0.0 END) * 100.0 / COUNT(customer_unique_id), 
        2
    ) AS repeat_customer_rate_pct
FROM customer_order_counts;


-- 2. RFM Metrics Calculation (Recency, Frequency, Monetary)
-- Reference snapshot date is set to the latest order timestamp in the dataset
WITH rfm_base AS (
    SELECT 
        c.customer_unique_id,
        c.customer_state,
        -- Recency: Days since last purchase
        ROUND(
            JULIANDAY((SELECT MAX(order_purchase_timestamp) FROM orders)) - 
            JULIANDAY(MAX(o.order_purchase_timestamp))
        ) AS recency_days,
        -- Frequency: Count of distinct orders
        COUNT(DISTINCT o.order_id) AS frequency,
        -- Monetary: Total spend
        ROUND(SUM(oi.price + oi.freight_value), 2) AS monetary_value
    FROM customers c
    JOIN orders o ON c.customer_id = o.customer_id
    JOIN order_items oi ON o.order_id = oi.order_id
    WHERE o.order_status = 'delivered'
    GROUP BY c.customer_unique_id, c.customer_state
),
rfm_scores AS (
    SELECT 
        customer_unique_id,
        customer_state,
        recency_days,
        frequency,
        monetary_value,
        NTILE(5) OVER (ORDER BY recency_days DESC) AS r_score,   -- 5 = most recent
        NTILE(5) OVER (ORDER BY frequency ASC) AS f_score,        -- 5 = most frequent
        NTILE(5) OVER (ORDER BY monetary_value ASC) AS m_score    -- 5 = highest spend
    FROM rfm_base
)
SELECT 
    customer_unique_id,
    customer_state,
    recency_days,
    frequency,
    monetary_value,
    r_score,
    f_score,
    m_score,
    CASE 
        WHEN r_score >= 4 AND f_score >= 4 AND m_score >= 4 THEN 'Champions'
        WHEN r_score >= 3 AND f_score >= 3 THEN 'Loyal Customers'
        WHEN r_score >= 4 AND f_score = 1 THEN 'Recent New Customers'
        WHEN r_score <= 2 AND f_score >= 3 THEN 'At Risk / Need Attention'
        WHEN r_score <= 1 AND f_score <= 2 THEN 'Lost Customers'
        ELSE 'Promising / Potential'
    END AS customer_segment
FROM rfm_scores
ORDER BY monetary_value DESC
LIMIT 50;


-- 3. Revenue & Customer Count by RFM Segment
WITH rfm_base AS (
    SELECT 
        c.customer_unique_id,
        ROUND(JULIANDAY((SELECT MAX(order_purchase_timestamp) FROM orders)) - JULIANDAY(MAX(o.order_purchase_timestamp))) AS recency_days,
        COUNT(DISTINCT o.order_id) AS frequency,
        ROUND(SUM(oi.price + oi.freight_value), 2) AS monetary_value
    FROM customers c
    JOIN orders o ON c.customer_id = o.customer_id
    JOIN order_items oi ON o.order_id = oi.order_id
    WHERE o.order_status = 'delivered'
    GROUP BY c.customer_unique_id
),
rfm_scores AS (
    SELECT 
        customer_unique_id,
        monetary_value,
        NTILE(5) OVER (ORDER BY recency_days DESC) AS r_score,
        NTILE(5) OVER (ORDER BY frequency ASC) AS f_score,
        NTILE(5) OVER (ORDER BY monetary_value ASC) AS m_score
    FROM rfm_base
),
segmented AS (
    SELECT 
        customer_unique_id,
        monetary_value,
        CASE 
            WHEN r_score >= 4 AND f_score >= 4 AND m_score >= 4 THEN 'Champions'
            WHEN r_score >= 3 AND f_score >= 3 THEN 'Loyal Customers'
            WHEN r_score >= 4 AND f_score = 1 THEN 'Recent New Customers'
            WHEN r_score <= 2 AND f_score >= 3 THEN 'At Risk / Need Attention'
            WHEN r_score <= 1 AND f_score <= 2 THEN 'Lost Customers'
            ELSE 'Promising / Potential'
        END AS customer_segment
    FROM rfm_scores
)
SELECT 
    customer_segment,
    COUNT(customer_unique_id) AS customer_count,
    ROUND(SUM(monetary_value), 2) AS total_segment_revenue,
    ROUND(AVG(monetary_value), 2) AS avg_revenue_per_customer
FROM segmented
GROUP BY customer_segment
ORDER BY total_segment_revenue DESC;
